#!/usr/bin/env bash
# Codex PreToolUse hook (harness/codex/tea-rags/scripts/one-file-read.sh, generated by
# scripts/gen-harness-codex.ts) rejects a shell command that prints more than one
# Markdown file. Codex eval: when a SKILL.md is read only inside a multi-file
# `cat a && cat b` / `python3 -c` loop, its output contract is lost (5/5 rounds).
# Single-file reads, `sed -n` ranges, listings, searches and non-.md reads pass.
set -u
ROOT="$(cd "$(dirname "$0")/../.." && pwd)"
HOOK="$ROOT/harness/codex/tea-rags/scripts/one-file-read.sh"
PASS=0; FAIL=0
note() { if [ "$1" = 0 ]; then PASS=$((PASS+1)); echo "ok   - $2"; else FAIL=$((FAIL+1)); echo "FAIL - $2"; fi; }

# run_hook <tool_input.command as JSON> → sets CODE and ERR
run_hook() {
  local input
  input=$(jq -cn --argjson command "$1" '{hook_event_name:"PreToolUse",tool_name:"Bash",tool_input:{command:$command}}')
  ERR=$(printf '%s' "$input" | bash "$HOOK" 2>&1 >/dev/null)
  CODE=$?
}
str() { jq -cn --arg s "$1" '$s'; }

allowed() { run_hook "$(str "$1")"; [ "$CODE" = 0 ]; note $? "allows: $1"; }
denied() {
  run_hook "$(str "$1")"
  [ "$CODE" = 2 ] && printf '%s' "$ERR" | grep -Fq "ONE file per command"
  note $? "denies: $1"
}

[ -f "$HOOK" ]
note $? "hook script is generated"

allowed 'cat a/SKILL.md'
denied 'cat a.md b.md'
denied 'cat a.md && cat b.md'
denied "python3 -c 'from pathlib import Path; [print(Path(p).read_text()) for p in [\"a.md\",\"b.md\"]]'"
denied 'for f in a.md b.md; do cat "$f"; done'
denied 'cat skills/*/SKILL.md'
denied "bash -lc 'cat a.md; cat b.md'"
denied $'python3 - <<\'PY\'\nfrom pathlib import Path\npaths = [\'/x/a/SKILL.md\',\'/x/b/SKILL.md\']\nfor p in paths: print(Path(p).read_text())\nPY'
denied $'cd /x && python3 <<-PY\n\tfor p in ["a.md", "b.md"]: print(open(p).read())\n\tPY'
denied $'node - <<"JS"\nfor (const p of ["a.md","b.md"]) console.log(require("fs").readFileSync(p,"utf8"))\nJS'
allowed $'python3 - <<\'PY\'\nfrom pathlib import Path\nprint(Path(\'/x/a/SKILL.md\').read_text())\nPY'
allowed $'python3 - <<\'PY\'\nimport os\nprint([os.path.exists(p) for p in [\'a.md\',\'b.md\']])\nPY'
allowed $'cat <<\'EOF\'\nsee a.md and b.md\nEOF'
allowed 'sed -n 1,200p a.md'
allowed 'rg -n foo a.md b.md'
allowed 'grep -n foo a.md b.md'
allowed 'ls x/*.md'
allowed 'find . -name "*.md"'
allowed 'cat a.ts b.ts'
allowed 'cat a.md > b.md'
allowed 'cat a.md a.md'
allowed "echo 'unbalanced"

# reason names the file count
run_hook "$(str 'cat a.md b.md c.md')"
printf '%s' "$ERR" | grep -Fq "prints 3 .md files"
note $? "reason names the file count"

# argv-array form of tool_input.command
run_hook '["bash","-lc","cat a.md && cat b.md"]'
[ "$CODE" = 2 ]
note $? "argv array: bash -lc with two .md reads is denied"
run_hook '["cat","a.md","b.md"]'
[ "$CODE" = 2 ]
note $? "argv array: cat of two .md files is denied"
run_hook '["sed","-n","1,80p","a.md"]'
[ "$CODE" = 0 ]
note $? "argv array: single-file sed range is allowed"

# malformed input never blocks
ERR=$(printf 'not json' | bash "$HOOK" 2>&1 >/dev/null); CODE=$?
[ "$CODE" = 0 ]
note $? "malformed stdin is allowed"

echo "# $PASS passed, $FAIL failed"
[ "$FAIL" = 0 ]
